import 'dart:convert';

import 'package:flutter/services.dart';

import 'package:drivio/features/theory_exam/models.dart';

/// Category B questions bundled in `assets/theory_exam/questions_b.json`,
/// generated by `tool/theory_exam/build_bank.py`.
class QuestionBank {
  QuestionBank({required this.questions, required this.sourceVersion})
    : _byId = {for (final q in questions) q.id: q};

  static const assetPath = 'assets/theory_exam/questions_b.json';

  final List<TheoryQuestion> questions;
  final String sourceVersion;
  final Map<int, TheoryQuestion> _byId;

  TheoryQuestion byId(int id) => _byId[id]!;

  TheoryQuestion? tryById(int id) => _byId[id];

  static QuestionBank fromJsonString(String source) {
    final json = jsonDecode(source) as Map<String, dynamic>;
    return QuestionBank(
      sourceVersion: json['sourceVersion'] as String,
      questions: [
        for (final q in json['questions'] as List)
          TheoryQuestion.fromJson(q as Map<String, dynamic>),
      ],
    );
  }

  static Future<QuestionBank> load(AssetBundle bundle) async =>
      fromJsonString(await bundle.loadString(assetPath));
}
